package com.citacloud.app.services;

import com.lowagie.text.Document;
import com.lowagie.text.FontFactory;
import com.lowagie.text.PageSize;
import com.lowagie.text.Paragraph;
import com.lowagie.text.Element;
import com.lowagie.text.pdf.PdfPCell;
import com.lowagie.text.pdf.PdfPTable;
import com.lowagie.text.pdf.PdfWriter;
import org.apache.poi.ss.usermodel.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.springframework.stereotype.Service;
import com.citacloud.app.models.*;
import java.io.*; import java.math.BigDecimal; import java.text.NumberFormat; import java.time.*; import java.time.format.DateTimeFormatter; import java.util.*;

@Service public class ReportesFinancierosExportService {
 public byte[] excel(ReportesFinancierosService.Resumen r,ReportesFinancierosService.Filtro f,String sucursal){return excel(r,f,sucursal,List.of(),List.of(),List.of());}
 public byte[] pdf(ReportesFinancierosService.Resumen r,ReportesFinancierosService.Filtro f,String sucursal,List<Factura> facturas,List<Pago> pagos,List<ReembolsoPago> reembolsos){try(ByteArrayOutputStream out=new ByteArrayOutputStream()){Document d=new Document(PageSize.A4,42,42,42,42);PdfWriter.getInstance(d,out);d.open();encabezado(d,f,sucursal);seccion(d,"RESUMEN FINANCIERO");PdfPTable resumen=tabla(new float[]{4,2,3});cabecera(resumen,"Concepto","Cantidad","Monto (RD$)");fila(resumen,"Facturado",r.facturas(),r.facturado());fila(resumen,"Cobrado",r.pagos(),r.cobrado());fila(resumen,"Por cobrar",r.cuentas(),r.porCobrar());fila(resumen,"Reembolsado",r.reembolsos(),r.reembolsado());d.add(resumen);seccion(d,"DETALLE FINANCIERO");PdfPTable detalle=tabla(new float[]{2,2,2.2f,4,2});cabecera(detalle,"Fecha","Tipo","Documento","Descripción","Monto (RD$)");for(Factura x:facturas)filaDetalle(detalle,fecha(x.getFecha()),"Factura",texto(x.getNumero()),"Factura "+texto(x.getNumero()),x.getTotal());for(Pago x:pagos)filaDetalle(detalle,fecha(x.getFecha()),"Pago",texto(x.getNumero()),"Pago registrado",x.getMonto());for(ReembolsoPago x:reembolsos)filaDetalle(detalle,fecha(x.getReembolsadoEn()==null?null:x.getReembolsadoEn().toLocalDate()),"Reembolso","REM-"+x.getId().toString().substring(0,8).toUpperCase(Locale.ROOT),"Reembolso registrado",x.getMonto());if(facturas.isEmpty()&&pagos.isEmpty()&&reembolsos.isEmpty())d.add(new Paragraph("No se encontraron registros para los filtros seleccionados."));else d.add(detalle);d.add(new Paragraph("\nLos valores corresponden a los filtros aplicados al reporte.",FontFactory.getFont(FontFactory.HELVETICA,8)));d.add(new Paragraph("Generado: "+LocalDateTime.now().format(DateTimeFormatter.ofPattern("dd/MM/yyyy hh:mm a")),FontFactory.getFont(FontFactory.HELVETICA,8)));d.close();return out.toByteArray();}catch(Exception e){throw new IllegalStateException("No se pudo generar el PDF financiero.",e);}}
 public byte[] excel(ReportesFinancierosService.Resumen r,ReportesFinancierosService.Filtro f,String sucursal,List<Factura> facturas,List<Pago> pagos,List<ReembolsoPago> reembolsos){try(Workbook w=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){CellStyle dinero=w.createCellStyle();dinero.setDataFormat(w.createDataFormat().getFormat("#,##0.00"));CellStyle fechaEstilo=w.createCellStyle();fechaEstilo.setDataFormat(w.createDataFormat().getFormat("dd/mm/yyyy"));CellStyle cab=w.createCellStyle();cab.setFillForegroundColor(IndexedColors.DARK_BLUE.getIndex());cab.setFillPattern(FillPatternType.SOLID_FOREGROUND);Font fuente=w.createFont();fuente.setColor(IndexedColors.WHITE.getIndex());fuente.setBold(true);cab.setFont(fuente);Sheet s=w.createSheet("Resumen");s.createRow(0).createCell(0).setCellValue("REPORTES FINANCIEROS");s.createRow(3).createCell(0).setCellValue("Período");s.getRow(3).createCell(1).setCellValue(fecha(f.desde())+" - "+fecha(f.hasta()));s.createRow(4).createCell(0).setCellValue("Sucursal");s.getRow(4).createCell(1).setCellValue(sucursal);s.createRow(5).createCell(0).setCellValue("Generado");s.getRow(5).createCell(1).setCellValue(LocalDateTime.now().format(DateTimeFormatter.ofPattern("dd/MM/yyyy hh:mm a")));s.createRow(8).createCell(0).setCellValue("RESUMEN FINANCIERO");Row h=s.createRow(10);String[] hs={"Concepto","Cantidad","Monto (RD$)"};for(int j=0;j<hs.length;j++){h.createCell(j).setCellValue(hs[j]);h.getCell(j).setCellStyle(cab);}int i=11;i=fila(s,i,"Facturado",r.facturado(),r.facturas(),dinero);i=fila(s,i,"Cobrado",r.cobrado(),r.pagos(),dinero);i=fila(s,i,"Por cobrar",r.porCobrar(),r.cuentas(),dinero);fila(s,i,"Reembolsado",r.reembolsado(),r.reembolsos(),dinero);for(int j=0;j<3;j++)s.autoSizeColumn(j);Sheet d=w.createSheet("Detalle");Row hd=d.createRow(0);String[] columnas={"Fecha","Tipo","Documento","Descripción","Monto (RD$)"};for(int j=0;j<columnas.length;j++){hd.createCell(j).setCellValue(columnas[j]);hd.getCell(j).setCellStyle(cab);}int fila=1;for(Factura x:facturas)fila=dato(d,fila,x.getFecha(),"Factura",texto(x.getNumero()),"Factura "+texto(x.getNumero()),x.getTotal(),fechaEstilo,dinero);for(Pago x:pagos)fila=dato(d,fila,x.getFecha(),"Pago",texto(x.getNumero()),"Pago registrado",x.getMonto(),fechaEstilo,dinero);for(ReembolsoPago x:reembolsos)fila=dato(d,fila,x.getReembolsadoEn()==null?null:x.getReembolsadoEn().toLocalDate(),"Reembolso","REM-"+x.getId().toString().substring(0,8).toUpperCase(Locale.ROOT),"Reembolso registrado",x.getMonto(),fechaEstilo,dinero);if(fila==1)d.createRow(fila).createCell(0).setCellValue("No se encontraron registros para los filtros seleccionados.");else{Row total=d.createRow(fila);total.createCell(3).setCellValue("TOTAL");var c=total.createCell(4);c.setCellFormula("SUM(E2:E"+fila+")");c.setCellStyle(dinero);d.setAutoFilter(new org.apache.poi.ss.util.CellRangeAddress(0,fila-1,0,4));d.createFreezePane(0,1);}d.setColumnWidth(0,4200);d.setColumnWidth(1,3500);d.setColumnWidth(2,5000);d.setColumnWidth(3,9000);d.setColumnWidth(4,4200);w.write(out);return out.toByteArray();}catch(Exception e){throw new IllegalStateException("No se pudo generar el Excel financiero.",e);}}
 private void encabezado(Document d,ReportesFinancierosService.Filtro f,String s)throws Exception{d.add(new Paragraph("REPORTES FINANCIEROS",FontFactory.getFont(FontFactory.HELVETICA_BOLD,18)));d.add(new Paragraph("Período: "+fecha(f.desde())+" - "+fecha(f.hasta()),FontFactory.getFont(FontFactory.HELVETICA,9)));d.add(new Paragraph("Sucursal: "+s,FontFactory.getFont(FontFactory.HELVETICA,9)));d.add(new Paragraph("Generado: "+LocalDateTime.now().format(DateTimeFormatter.ofPattern("dd/MM/yyyy hh:mm a")),FontFactory.getFont(FontFactory.HELVETICA,9)));d.add(new Paragraph("____________________________________________________________"));} private void seccion(Document d,String n)throws Exception{Paragraph p=new Paragraph("\n"+n,FontFactory.getFont(FontFactory.HELVETICA_BOLD,11));p.setSpacingAfter(8);d.add(p);} private PdfPTable tabla(float[] w){PdfPTable t=new PdfPTable(w);t.setWidthPercentage(100);t.setHeaderRows(1);return t;} private void cabecera(PdfPTable t,String... h){for(String x:h){PdfPCell c=new PdfPCell(new Paragraph(x,FontFactory.getFont(FontFactory.HELVETICA_BOLD,9,java.awt.Color.WHITE)));c.setBackgroundColor(new java.awt.Color(30,64,120));c.setPadding(7);t.addCell(c);}} private void fila(PdfPTable t,String n,long c,BigDecimal m){celda(t,n,Element.ALIGN_LEFT);celda(t,String.valueOf(c),Element.ALIGN_RIGHT);celda(t,monto(m),Element.ALIGN_RIGHT);} private void filaDetalle(PdfPTable t,String... x){for(int i=0;i<4;i++)celda(t,x[i],Element.ALIGN_LEFT);celda(t,x[4],Element.ALIGN_RIGHT);} private void filaDetalle(PdfPTable t,String f,String tipo,String doc,String d,BigDecimal m){filaDetalle(t,f,tipo,doc,d,monto(m));} private void celda(PdfPTable t,String x,int a){PdfPCell c=new PdfPCell(new Paragraph(x,FontFactory.getFont(FontFactory.HELVETICA,8)));c.setHorizontalAlignment(a);c.setPadding(5);c.setBorderColor(new java.awt.Color(220,220,220));t.addCell(c);} private String monto(BigDecimal x){return NumberFormat.getNumberInstance(Locale.US).format((x==null?BigDecimal.ZERO:x).setScale(2));} private int fila(Sheet s,int i,String n,BigDecimal m,long c,CellStyle estilo){Row r=s.createRow(i);r.createCell(0).setCellValue(n);r.createCell(1).setCellValue(c);r.createCell(2).setCellValue(m.doubleValue());r.getCell(2).setCellStyle(estilo);return i+1;} private int dato(Sheet s,int i,LocalDate fecha,String tipo,String doc,String descripcion,BigDecimal monto,CellStyle fechaEstilo,CellStyle dinero){Row r=s.createRow(i);if(fecha!=null){r.createCell(0).setCellValue(java.sql.Date.valueOf(fecha));r.getCell(0).setCellStyle(fechaEstilo);}else r.createCell(0).setCellValue("—");r.createCell(1).setCellValue(tipo);r.createCell(2).setCellValue(doc);r.createCell(3).setCellValue(descripcion);r.createCell(4).setCellValue(monto.doubleValue());r.getCell(4).setCellStyle(dinero);return i+1;} private String fecha(java.time.LocalDate d){return d==null?"—":d.format(DateTimeFormatter.ofPattern("dd/MM/yyyy"));} private String texto(String x){return x==null||x.isBlank()?"—":x;}
}
